import json,base64
from collections import defaultdict,Counter
notes=defaultdict(list); noPt=[]
for l in open('DocumentReference.ndjson'):
    d=json.loads(l)
    if 'subject' in d: notes[d['subject']['reference'].split('/')[-1]].append(d)
    else: noPt.append(d)
print(len(notes), len(noPt))
c=Counter()
for v in list(notes.values())+[noPt]:
    for d in v:
        for e in d.get('extension',[]):
            c[(e['url'].split('/')[-1], e.get('valueCode'))]+=1
        c[('type',d['type']['coding'][0]['display'])]+=1
        c[('prof',tuple(d['meta']['profile']))]+=1
for k,v in c.items(): print(v,k)
"

